function formatKeyword(keyword) {
    // Convert camelCase or lowercase words to proper spacing
    return keyword.replace(/([a-z])([A-Z])/g, '$1 $2') // camelCase to space
    .replace(/([a-z])([0-9])/g, '$1 $2') // letter followed by number
    .replace(/([0-9])([a-z])/g, '$1 $2') // number followed by letter
    .split(' ').map((word)=>word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()).join(' ');
}
// Helper function to format market cap
function formatMarketCap(value) {
    if (value >= 1e12) {
        return "$".concat((value / 1e12).toFixed(1), "T");
    } else if (value >= 1e9) {
        return "$".concat((value / 1e9).toFixed(1), "B");
    } else if (value >= 1e6) {
        return "$".concat((value / 1e6).toFixed(1), "M");
    } else if (value >= 1e3) {
        return "$".concat((value / 1e3).toFixed(1), "K");
    } else {
        return "$".concat(value.toFixed(0));
    }
}
